import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { PLATFORM_ADMIN_API_ROLES } from '@/lib/auth/rbac'

interface PgSettingRow {
  active: number
  max_conn: number
}

// AUTO-GENERATED by api-row-sweep --apply — REVIEW these column types.
// pg returns bigint/numeric as string, timestamptz as Date; add `| null` where nullable.
interface ErrorLogRow {
  message: string
  created_at: string
  endpoint: string | null
}

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/health
 *
 * Returns system health metrics with historical trend data
 * for the admin dashboard health monitoring panel.
 * Requires auth + admin role.
 */
export const GET = apiHandler(
  { auth: true, roles: PLATFORM_ADMIN_API_ROLES, rateLimit: { max: 120, windowMs: 60000 } },
  async (_req, _ctx) => {
    const startTime = Date.now()

    // ── Current health snapshot ──
    let dbStatus = 'healthy'
    let dbLatencyMs = 0
    try {
      const healthStart = Date.now()
      await db.query<never>('SELECT 1')
      dbLatencyMs = Date.now() - healthStart
    } catch {
      dbStatus = 'unhealthy'
    }

    const uptime = process.uptime()
    const memoryUsage = process.memoryUsage()
    const responseTime = Date.now() - startTime

    // Historical percentiles, uptime, and error rates require persistent
    // telemetry. Return empty series until those observations are stored.
    const responseTimeTrends: { timestamp: string; p50: number; p95: number; p99: number }[] = []
    const uptimeTrends7d: { date: string; uptime: number }[] = []
    const uptimeTrends30d: { date: string; uptime: number }[] = []
    const errorRateTrends: { timestamp: string; rate: number; count: number }[] = []

    // ── DB connection stats (PostgreSQL) ──
    let dbConnections = 0
    let dbConnectionsMax = 100
    try {
      const connRes = await db.query<PgSettingRow>(
        `SELECT count(*)::int AS active, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_conn FROM pg_stat_activity WHERE datname = current_database()`
      )
      dbConnections = connRes.rows[0]?.active ?? 0
      dbConnectionsMax = connRes.rows[0]?.max_conn ?? 100
    } catch {
      // Non-critical — may not have pg_stat_activity access
    }

    // ── Recent errors from DB (if available) ──
    let recentErrors: { message: string; timestamp: string; endpoint: string }[] = []
    try {
      const errorsRes = await db.query<ErrorLogRow>(
        `SELECT message, created_at, endpoint FROM error_logs ORDER BY created_at DESC LIMIT 10`
      )
      recentErrors = errorsRes.rows.map((row) => ({
        message: row.message,
        timestamp: row.created_at,
        endpoint: row.endpoint ?? 'unknown',
      }))
    } catch {
      // error_logs table may not exist
    }

    return apiSuccess({
      current: {
        database: {
          status: dbStatus,
          latencyMs: dbLatencyMs,
          connections: dbConnections,
          connectionsMax: dbConnectionsMax,
        },
        uptime: Math.floor(uptime),
        uptimePercent: null,
        memory: {
          heapUsedMb: Math.round(memoryUsage.heapUsed / 1024 / 1024),
          heapTotalMb: Math.round(memoryUsage.heapTotal / 1024 / 1024),
          rssMb: Math.round(memoryUsage.rss / 1024 / 1024),
          externalMb: Math.round((memoryUsage.external || 0) / 1024 / 1024),
        },
        responseTimeMs: responseTime,
      },
      trends: {
        responseTime: responseTimeTrends,
        uptime7d: uptimeTrends7d,
        uptime30d: uptimeTrends30d,
        errorRate: errorRateTrends,
      },
      recentErrors,
    })
  },
)
